52	// A registered device's authored documents are listed, each once, sorted by
53	// id, regardless of write order or which session wrote them; documents other
54	// devices wrote never appear.
55	func TestListDocumentsContract(t *testing.T) {
56		h, _ := newTestHandler(t)
57		registerDevice(t, h, "dev-1")
58		registerDevice(t, h, "dev-2")
59		createSessions(t, h, "dev-1", "sess-a", "sess-b")
60		createSessions(t, h, "dev-2", "sess-foreign")
61	
62		// Two sessions of dev-1 write across three docs, out of order; doc-c gets
63		// a second change (it must still appear once).
64		commitSessionChange(t, h, "sess-a", "doc-c", "c1")
65		commitSessionChange(t, h, "sess-b", "doc-a", "c2")
66		commitSessionChange(t, h, "sess-a", "doc-b", "c3")
67		commitSessionChange(t, h, "sess-b", "doc-c", "c4")
68		commitSessionChange(t, h, "sess-foreign", "doc-foreign", "c5")
