71		if w.Code != http.StatusOK {
72			t.Fatalf("status = %d body=%s", w.Code, w.Body.String())
73		}
74		want := []string{"doc-a", "doc-b", "doc-c"}
75		if !equalStrings(ids, want) {
76			t.Fatalf("order = %v, want %v", ids, want)
77		}
78		if count != len(ids) {
79			t.Fatalf("count = %d, want %d", count, len(ids))
80		}
81	
82		// Each item carries only the documentId key.
83		var body struct {
84			Documents []map[string]json.RawMessage `json:"documents"`
85		}
86		if err := json.Unmarshal(w.Body.Bytes(), &body); err != nil {
87			t.Fatal(err)
88		}
89		for _, item := range body.Documents {
90			if len(item) != 1 {
91				t.Fatalf("item %v must have exactly one key", item)
92			}
93			if _, ok := item["documentId"]; !ok {
94				t.Fatalf("item %v must carry documentId", item)
95			}
96		}
97	
98		// The other device sees only its own document.
99		_, ids, _ = listDocuments(t, h, "/v1/devices/dev-2/documents")
100		if !equalStrings(ids, []string{"doc-foreign"}) {
101			t.Fatalf("dev-2 list = %v", ids)
