149			t.Fatalf("body must be one line plus a trailing newline: %q", body)
150		}
151		if strings.Contains(body, ", ") || strings.Contains(body, ": ") {
152			t.Fatalf("body must be compact JSON: %q", body)
153		}
154		want := `{"documents":[{"documentId":"d1"},{"documentId":"d2"}],"count":2}` + "\n"
155		if body != want {
156			t.Fatalf("body = %q, want %q", body, want)
157		}
158	}
159	
160	// limit/offset page the fixed order without repeats or gaps; defaults and the
161	// 1..1000 bounds behave like the attachment listing.
162	func TestListDocumentsPagination(t *testing.T) {
163		h, _ := newTestHandler(t)
164		registerDevice(t, h, "dev")
165		createSessions(t, h, "dev", "sess")
166		for _, doc := range []string{"d0", "d1", "d2", "d3", "d4"} {
167			commitSessionChange(t, h, "sess", doc, "c-"+doc)
168		}
169	
170		// Default limit is 100: one page holds everything in id order.
171		_, ids, _ := listDocuments(t, h, "/v1/devices/dev/documents")
172		if !equalStrings(ids, []string{"d0", "d1", "d2", "d3", "d4"}) {
173			t.Fatalf("default page = %v", ids)
174		}
175	
176		// Walk the list in pages of two: no duplicates, no gaps.
177		var seen []string
178		for offset := 0; offset < 5; offset += 2 {
179			_, page, count := listDocuments(t, h, fmt.Sprintf("/v1/devices/dev/documents?limit=2&offset=%d", offset))
180			if count != len(page) {
181				t.Fatalf("page at offset %d count = %d, len = %d", offset, count, len(page))
182			}
183			seen = append(seen, page...)
184		}
185		if !equalStrings(seen, []string{"d0", "d1", "d2", "d3", "d4"}) {
186			t.Fatalf("paged walk = %v", seen)
187		}
188	
189		// Partial last page and a page past the end.
190		_, page, _ := listDocuments(t, h, "/v1/devices/dev/documents?limit=4&offset=3")
191		if !equalStrings(page, []string{"d3", "d4"}) {
192			t.Fatalf("last partial page = %v", page)
193		}
194		w, page, count := listDocuments(t, h, "/v1/devices/dev/documents?offset=5")
195		if w.Code != http.StatusOK || len(page) != 0 || count != 0 {
196			t.Fatalf("page past end = %d %v count=%d", w.Code, page, count)
197		}
198	
199		// The accepted bounds.
200		for _, query := range []string{"limit=1", "limit=1000", "offset=0"} {
201			r := httptest.NewRequest(http.MethodGet, "/v1/devices/dev/documents?"+query, nil)
202			if rec := serveRecorder(h, r); rec.Code != http.StatusOK {
203				t.Fatalf("?%s = %d", query, rec.Code)
204			}
205		}
206	}
207	
208	// Illegal pagination values are a 400 JSON error checked before the device
209	// lookup; an unregistered device is a 404 JSON error with no listing content.
210	func TestListDocumentsRejectsBadParams(t *testing.T) {
211		h, _ := newTestHandler(t)
212		registerDevice(t, h, "dev-1")
213		createSessions(t, h, "dev-1", "sess")
214		commitSessionChange(t, h, "sess", "doc-1", "c1")
215	
216		for _, query := range []string{
217			"limit=0", "limit=-1", "limit=1001", "limit=x", "limit=1.5",
218			"offset=-1", "offset=x", "offset=1.5",
219		} {
220			r := httptest.NewRequest(http.MethodGet, "/v1/devices/dev-1/documents?"+query, nil)
221			w := serveRecorder(h, r)
222			if w.Code != http.StatusBadRequest {
223				t.Fatalf("?%s = %d, want 400 body=%s", query, w.Code, w.Body.String())
224			}
225			assertJSONError(t, w)
226		}
227	
228		// Unregistered device: 404 JSON with no listing content.
229		r := httptest.NewRequest(http.MethodGet, "/v1/devices/ghost/documents", nil)
230		w := serveRecorder(h, r)
231		if w.Code != http.StatusNotFound {
232			t.Fatalf("unknown device = %d, want 404", w.Code)
233		}
234		assertJSONError(t, w)
235		if strings.Contains(w.Body.String(), "doc-1") || strings.Contains(w.Body.String(), "documents") {
236			t.Fatalf("404 body leaks listing: %s", w.Body.String())
237		}
238	
239		// Shape errors win over the device lookup: 400 even for a ghost device.
240		r = httptest.NewRequest(http.MethodGet, "/v1/devices/ghost/documents?limit=0", nil)
241		if rec := serveRecorder(h, r); rec.Code != http.StatusBadRequest {
242			t.Fatalf("ghost with bad limit = %d, want 400", rec.Code)
243		}
244	
245		// None of the rejections changed the listing.
246		_, ids, _ := listDocuments(t, h, "/v1/devices/dev-1/documents")
247		if !equalStrings(ids, []string{"doc-1"}) {
248			t.Fatalf("list after rejections = %v", ids)
249		}
250	}
251	
252	// Empty identifiers, trailing slashes, extra segments and verbs other than
253	// GET on the collection path are all 400 JSON errors — never a redirect or
254	// HTML — and change nothing.
255	func TestListDocumentsShapeContract(t *testing.T) {
256		h, _ := newTestHandler(t)
257		registerDevice(t, h, "dev-1")
258		createSessions(t, h, "dev-1", "sess")
259		commitSessionChange(t, h, "sess", "doc-1", "c1")
260	
261		cases := []struct {
262			name   string
263			method string
264			path   string
265		}{
266			{"empty device segment", http.MethodGet, "/v1/devices//documents"},
267			{"trailing slash on collection", http.MethodGet, "/v1/devices/dev-1/documents/"},
268			{"extra segment on get", http.MethodGet, "/v1/devices/dev-1/documents/doc-1"},
269			{"two extra segments on get", http.MethodGet, "/v1/devices/dev-1/documents/doc-1/extra"},
270			{"post on the collection", http.MethodPost, "/v1/devices/dev-1/documents"},
271			{"put on the collection", http.MethodPut, "/v1/devices/dev-1/documents"},
272			{"patch on the collection", http.MethodPatch, "/v1/devices/dev-1/documents"},
273			{"delete on the collection", http.MethodDelete, "/v1/devices/dev-1/documents"},
274			{"post past the collection", http.MethodPost, "/v1/devices/dev-1/documents/doc-1"},
275			{"delete past the collection", http.MethodDelete, "/v1/devices/dev-1/documents/doc-1"},
276		}
277		for _, tc := range cases {
278			t.Run(tc.name, func(t *testing.T) {
279				r := httptest.NewRequest(tc.method, tc.path, nil)
280				w := serveRecorder(h, r)
281				if w.Code != http.StatusBadRequest {
282					t.Fatalf("%s %s = %d, want 400", tc.method, tc.path, w.Code)
283				}
284				assertJSONError(t, w)
285				if loc := w.Header().Get("Location"); loc != "" {
286					t.Fatalf("malformed request produced a redirect to %q", loc)
287				}
288			})
289		}
290	
291		// Zero writes: the listing is unchanged and a GET body is ignored by the
292		// read-only route.
293		_, ids, _ := listDocuments(t, h, "/v1/devices/dev-1/documents")
294		if !equalStrings(ids, []string{"doc-1"}) {
295			t.Fatalf("list after rejected shapes = %v", ids)
296		}
297	}
298	
299	// A GET with an unexpected body still answers the read-only listing and
300	// creates nothing.
301	func TestListDocumentsIgnoresBody(t *testing.T) {
302		h, _ := newTestHandler(t)
303		registerDevice(t, h, "dev")
304		createSessions(t, h, "dev", "sess")
305		commitSessionChange(t, h, "sess", "doc", "c1")
306	
307		r := httptest.NewRequest(http.MethodGet, "/v1/devices/dev/documents", strings.NewReader(`{"documentId":"ignored"}`))
308		r.Header.Set("Content-Type", "application/json")
309		w := serveRecorder(h, r)
310		if w.Code != http.StatusOK {
311			t.Fatalf("GET with body = %d %s", w.Code, w.Body.String())
312		}
313		_, ids, count := listDocuments(t, h, "/v1/devices/dev/documents")
314		if count != 1 || !equalStrings(ids, []string{"doc"}) {
315			t.Fatalf("listing changed after a GET: %v", ids)
316		}
317	}
318	
319	// Deleting a whole document removes it from the listing; compacting every
320	// change out of the online log removes it too. Other documents survive.
321	func TestListDocumentsReflectsDeleteAndCompaction(t *testing.T) {
322		h, _ := newTestHandler(t)
323		registerDevice(t, h, "dev")
324		createSessions(t, h, "dev", "sess")
325		commitSessionChange(t, h, "sess", "doc-a", "a1")
326		commitSessionChange(t, h, "sess", "doc-b", "b1")
327	
328		// Whole-document delete removes doc-a.
329		w, _ := doRequest(t, h, http.MethodDelete, "/v1/documents/doc-a?deviceId=dev")
330		if w.Code != http.StatusOK {
331			t.Fatal(w.Body.String())
332		}
333		_, ids, _ := listDocuments(t, h, "/v1/devices/dev/documents")
334		if !equalStrings(ids, []string{"doc-b"}) {
335			t.Fatalf("list after document delete = %v", ids)
336		}
337	
338		// Pin a snapshot at doc-b's last cursor and compact: its change leaves
339		// the online log, so the document no longer appears.
340		w, _ = postJSON(t, h, "/v1/documents/doc-b/snapshots", map[string]any{
341			"cursor": 1,
342			"state":  map[string]int{"n": 1},
343		})
344		if w.Code != http.StatusOK {
345			t.Fatal(w.Body.String())
346		}
347		w, _ = postJSON(t, h, "/v1/documents/doc-b/changes/compact", map[string]any{"deviceId": "dev"})
348		if w.Code != http.StatusOK {
349			t.Fatal(w.Body.String())
350		}
351		rec, ids, count := listDocuments(t, h, "/v1/devices/dev/documents")
352		if rec.Code != http.StatusOK || count != 0 || len(ids) != 0 {
353			t.Fatalf("list after full compaction = %d %v count=%d", rec.Code, ids, count)
354		}
355	
356		// A fresh change on the compacted document brings it back.
357		commitSessionChange(t, h, "sess", "doc-b", "b2")
358		_, ids, _ = listDocuments(t, h, "/v1/devices/dev/documents")
359		if !equalStrings(ids, []string{"doc-b"}) {
360			t.Fatalf("list after new change = %v", ids)
361		}
362	}
363	
364	// While deregistered a device's listing answers the same 404 a
365	// never-registered device gets; other devices' listings survive. The shared
366	// change log is deliberately preserved across deregistration (the baseline
367	// cascade keeps every authored change for collaborators), so after the same
368	// id re-registers the surviving online changes it authored still name it and
369	// their documents list again; only a deleted or fully compacted document is
370	// gone.
371	func TestListDocumentsReflectsDeregister(t *testing.T) {
372		h, _ := newTestHandler(t)
373		registerDevice(t, h, "dev-1")
374		registerDevice(t, h, "dev-2")
375		createSessions(t, h, "dev-1", "s1")
376		createSessions(t, h, "dev-2", "s2")
377		commitSessionChange(t, h, "s1", "doc-a", "a1")
378		commitSessionChange(t, h, "s2", "doc-b", "b1")
379	
380		w, _ := doRequest(t, h, http.MethodDelete, "/v1/devices/dev-1")
381		if w.Code != http.StatusOK {
382			t.Fatal(w.Body.String())
383		}
384		r := httptest.NewRequest(http.MethodGet, "/v1/devices/dev-1/documents", nil)
385		if rec := serveRecorder(h, r); rec.Code != http.StatusNotFound {
386			t.Fatalf("list while deregistered = %d, want 404", rec.Code)
387		}
388		_, ids, _ := listDocuments(t, h, "/v1/devices/dev-2/documents")
389		if !equalStrings(ids, []string{"doc-b"}) {
390			t.Fatalf("other device after deregister = %v", ids)
391		}
392	
393		// The shared change log survived: re-registering the same id lets its
394		// surviving authored change list doc-a again. New writes appear alongside
395		// it like on any device.
396		registerDevice(t, h, "dev-1")
397		_, ids, count := listDocuments(t, h, "/v1/devices/dev-1/documents")
398		if count != 1 || !equalStrings(ids, []string{"doc-a"}) {
399			t.Fatalf("re-registered device list = %v count=%d", ids, count)
400		}
401		createSessions(t, h, "dev-1", "s1-new")
402		commitSessionChange(t, h, "s1-new", "doc-c", "c1")
403		_, ids, _ = listDocuments(t, h, "/v1/devices/dev-1/documents")
404		if !equalStrings(ids, []string{"doc-a", "doc-c"}) {
405			t.Fatalf("list after a new write = %v", ids)
406		}
407	}
408	
409	// The keyword "documents" as a device id is an ordinary identifier; the word
410	// is an endpoint segment only in its fixed position.
411	func TestListDocumentsKeywordAsDeviceID(t *testing.T) {
412		h, _ := newTestHandler(t)
413	
414		// Unregistered device literally named "documents": same 404 as any other
415		// unregistered id, reached on the ordinary collection route.
416		r := httptest.NewRequest(http.MethodGet, "/v1/devices/documents/documents", nil)
417		w := serveRecorder(h, r)
418		if w.Code != http.StatusNotFound {
419			t.Fatalf("device id 'documents' = %d, want 404", w.Code)
420		}
421		assertJSONError(t, w)
422	
423		// Once registered it behaves like every other device: writes and lists.
424		registerDevice(t, h, "documents")
425		createSessions(t, h, "documents", "sess")
426		commitSessionChange(t, h, "sess", "doc", "c1")
427		_, ids, count := listDocuments(t, h, "/v1/devices/documents/documents")
428		if count != 1 || !equalStrings(ids, []string{"doc"}) {
429			t.Fatalf("device id 'documents' list = %v count=%d", ids, count)
430		}
431	}
432	
433	// Repeated reads and reads across a process restart return byte-identical
434	// bodies; the read changes nothing.
435	func TestListDocumentsDeterministicAndDurable(t *testing.T) {
436		dbPath := filepath.Join(t.TempDir(), "sync.db")
437		open := func(t *testing.T) (http.Handler, *app.App) {
438			t.Helper()
439			s, err := app.Open(dbPath)
440			if err != nil {
441				t.Fatal(err)
442			}
443			return NewHandler(s), s
444		}
445	
446		h, s := open(t)
447		registerDevice(t, h, "dev")
448		createSessions(t, h, "dev", "sess")
449		for _, doc := range []string{"doc-c", "doc-a", "doc-b"} {
450			commitSessionChange(t, h, "sess", doc, "c-"+doc)
451		}
452	
453		snapshot := func() map[string]string {
454			bodies := map[string]string{}
455			for _, url := range []string{
456				"/v1/devices/dev/documents",
457				"/v1/devices/dev/documents?limit=1&offset=0",
458				"/v1/devices/dev/documents?limit=1&offset=1",
459				"/v1/devices/dev/documents?limit=1&offset=2",
460				"/v1/devices/dev/documents?offset=3",
461			} {
462				r := httptest.NewRequest(http.MethodGet, url, nil)
463				w := serveRecorder(h, r)
464				if w.Code != http.StatusOK {
465					t.Fatalf("GET %s = %d", url, w.Code)
466				}
467				bodies[url] = w.Body.String()
468			}
469			return bodies
470		}
471	
472		before := snapshot()
473		// An immediate repeat is byte-for-byte identical.
474		if again := snapshot(); fmt.Sprint(again) != fmt.Sprint(before) {
475			t.Fatalf("repeat read changed:\nbefore=%v\nafter=%v", before, again)
476		}
477		if err := s.Close(); err != nil {
478			t.Fatal(err)
479		}
480	
481		h, s = open(t)
482		defer func() { _ = s.Close() }()
483		after := snapshot()
484		for url, body := range before {
485			if after[url] != body {
486				t.Fatalf("GET %s after restart = %q, want %q", url, after[url], body)
487			}
488		}
489	}
