	r = httptest.NewRequest(http.MethodGet, "/v1/devices/ghost/documents?limit=0", nil)
	if rec := serveRecorder(h, r); rec.Code != http.StatusBadRequest {
		t.Fatalf("ghost with bad limit = %d, want 400", rec.Code)
	}

